package fr.formation.hexagonal.application.service;import fr.formation.hexagonal.application.port.in.ManageRoomUseCase;import fr.formation.hexagonal.application.port.out.RoomPort;import fr.formation.hexagonal.domain.Room;import java.util.*;public final class RoomService implements ManageRoomUseCase{private final RoomPort rooms;public RoomService(RoomPort rooms){this.rooms=rooms;}public Room create(String name,int capacity){return rooms.save(new Room(UUID.randomUUID(),name,capacity));}public List<Room>list(){return rooms.findAll();}}
